import type { ImgHTMLAttributes } from 'react';
import { assetUrl } from '../../utils/assetUrl';

/** Individual SVG assets generated by npm predev, pretest and prebuild. */
export type Gnz2DIconName =
  | 'empire' | 'play' | 'continue' | 'save' | 'load' | 'settings' | 'trophy'
  | 'book' | 'map' | 'download' | 'network' | 'city' | 'science' | 'culture'
  | 'gold' | 'production' | 'food' | 'population' | 'diplomacy' | 'war'
  | 'scout' | 'economy' | 'government' | 'up' | 'down' | 'left' | 'right'
  | 'close' | 'check' | 'info' | 'warning' | 'search' | 'star' | 'shield'
  | 'peace' | 'trade' | 'movement' | 'health' | 'worker' | 'settler'
  | 'fortify' | 'ship' | 'quest' | 'eye' | 'lock' | 'plus' | 'minus'
  | 'filter' | 'sort' | 'castle' | 'ruins' | 'resource' | 'world' | 'hammer'
  | 'calendar' | 'cloud' | 'exit' | 'person' | 'building' | 'minimap'
  | 'hex' | 'menu' | 'archer' | 'cavalry' | 'mine' | 'farm' | 'forest'
  | 'mountain' | 'ocean' | 'desert';

export function Gnz2DAsset({
  name,
  size = 'md',
  alt = '',
  loading = 'eager',
  draggable = false,
  ...props
}: Omit<ImgHTMLAttributes<HTMLImageElement>, 'src'> & {
  name: Gnz2DIconName;
  size?: 'sm' | 'md' | 'lg';
}) {
  return (
    <img
      src={assetUrl('ui-2d/icon-' + name + '-' + size + '.svg')}
      alt={alt}
      loading={loading}
      draggable={draggable}
      decoding="async"
      {...props}
    />
  );
}
